def solve(g):
    g = np.array(g); H,W = g.shape
    walls = (g==3)
    R = np.where(walls.all(axis=1))[0][0]   # horizontal wall row
    C = np.where(walls.all(axis=0))[0][0]   # vertical wall col
    out = np.zeros_like(g)
    k = 1
    while R-2*k >= 0 or R+2*k < H or C-2*k >= 0 or C+2*k < W:
        for r in (R-2*k, R+2*k):
            if 0 <= r < H:
                for c in range(max(0, C-2*k), min(W-1, C+2*k)+1):
                    if not walls[r,c]: out[r,c] = 4
        for c in (C-2*k, C+2*k):
            if 0 <= c < W:
                for r in range(max(0, R-2*k), min(H-1, R+2*k)+1):
                    if not walls[r,c]: out[r,c] = 4
        k += 1
    out[walls] = 3
    return out.tolist()

